def greet(name):
    if not name:
        raise ValueError("name required")
    return f"Hello, {name}!"

from src.greeting import greet


def test_ordinary():
    assert greet("Ada") == "Hello, Ada!"


def test_empty():
    try:
        greet("")
    except ValueError:
        return
    raise AssertionError("empty name accepted")

